import{_ as a,c as o,o as e,ag as l}from"./chunks/framework._xRlcm3f.js";const u=JSON.parse('{"title":"知乎配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-zhihu.md","filePath":"platforms/custom-zhihu.md","lastUpdated":1790228279000}'),i={name:"platforms/custom-zhihu.md"};function r(d,t,s,h,n,c){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="知乎配置指南" tabindex="-1">知乎配置指南 <a class="header-anchor" href="#知乎配置指南" aria-label="Permalink to &quot;知乎配置指南&quot;">​</a></h1><p>通过 <strong>Cookie 授权</strong>发布到知乎专栏。图片默认上传到知乎。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li><p>在浏览器登录知乎。</p></li><li><p>记下自己的知乎<strong>用户名</strong>——打开个人主页，看地址栏 <code>zhihu.com/people/&lt;用户名&gt;</code>，斜杠后面那一段就是。</p><div class="tip custom-block"><p class="custom-block-title">用户名填错的后果</p><p>填错就读不到专栏列表。验证这一步本质是<strong>获取专栏</strong>，用户名必须正确。</p></div></li><li><p>无需 API Token，只用 Cookie。</p></li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>默认 <code>https://zhuanlan.zhihu.com</code>，一般不改</td></tr><tr><td>API 地址</td><td>默认知乎专栏 API，一般不改</td></tr><tr><td>用户名</td><td>知乎用户名（个人主页地址里那一段），必须填对</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/p/[postid]</code></td></tr><tr><td>发布格式</td><td><strong>必须选 HTML</strong>，知乎目前只接受 HTML 模式</td></tr><tr><td>专栏</td><td>发布目标专栏；验证通过后从列表选择</td></tr><tr><td>图床</td><td>默认「当前平台」，图片随文章上传到知乎</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">发布格式必须是 HTML</p><p>知乎目前<strong>只能选择 HTML 模式</strong>发布。选 Markdown 会出现发布异常。CSDN 同理。</p></div><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 登录知乎 → <strong>关闭登录窗口</strong> → 点「2 自动读取 Cookie」。</li><li>填好用户名，点「验证」→ 通过后会列出你的专栏，选择要发布到的那个并保存。</li><li>快速发布 → 选知乎 → 发布。</li></ol><div class="tip custom-block"><p class="custom-block-title">没有专栏也能用</p><p>不设置专栏不影响发布，只是文章不会被收录到专栏里。之后可以随时回来修改。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="为什么不能改所属专栏" tabindex="-1">为什么不能改所属专栏 <a class="header-anchor" href="#为什么不能改所属专栏" aria-label="Permalink to &quot;为什么不能改所属专栏&quot;">​</a></h3><p>知乎平台限制，已发布文档暂不支持编辑专栏。取消或删除原文后，重新选择专栏发布。</p><h3 id="读取不到专栏" tabindex="-1">读取不到专栏 <a class="header-anchor" href="#读取不到专栏" aria-label="Permalink to &quot;读取不到专栏&quot;">​</a></h3><ol><li>确认「用户名」填的是知乎用户名（个人主页地址里那一段），不是昵称。</li><li>确认已读取 Cookie。</li><li>再点验证。验证通过后专栏列表才会出现，选中后保存。</li></ol><h3 id="验证通过但无法发布" tabindex="-1">验证通过但无法发布 <a class="header-anchor" href="#验证通过但无法发布" aria-label="Permalink to &quot;验证通过但无法发布&quot;">​</a></h3><p>多半是<strong>账号不一致</strong>造成的。典型情况：手机用微信登录、电脑用手机号登录，两者不是同一个账号；再用手机知乎扫码登录，会让账号处于<strong>未绑定</strong>状态。</p><p>请确认登录用的是同一个账号。如果仍然不行，可以重置配置：</p><ol><li>卸载插件后重新安装；</li><li>或删除 <code>[工作空间]/data/storage/syp/sy-p-plus-cfg.json</code>，然后重新添加并配置该平台。</li></ol><div class="warning custom-block"><p class="custom-block-title">重置会清掉全部平台配置</p><p>删除配置文件会丢失<strong>所有</strong>平台账号配置，不只是知乎。操作前请先备份该文件，并关闭思源后再操作。</p></div><h3 id="cookie-验证失败" tabindex="-1">Cookie 验证失败 <a class="header-anchor" href="#cookie-验证失败" aria-label="Permalink to &quot;Cookie 验证失败&quot;">​</a></h3><p>确认浏览器已登录知乎、账号能打开创作中心，然后重新读取 Cookie。Cookie 会过期，过期后按上面的流程重新授权即可。</p><h3 id="报错「您当前请求存在异常-暂时限制本次访问」" tabindex="-1">报错「您当前请求存在异常，暂时限制本次访问」 <a class="header-anchor" href="#报错「您当前请求存在异常-暂时限制本次访问」" aria-label="Permalink to &quot;报错「您当前请求存在异常，暂时限制本次访问」&quot;">​</a></h3><p>知乎已限制在 Electron 内登录，只能复制 Cookie。请升级到最新版插件，然后删除该平台账号重新导入。</p><h3 id="图片图床" tabindex="-1">图片图床 <a class="header-anchor" href="#图片图床" aria-label="Permalink to &quot;图片图床&quot;">​</a></h3><p>默认「当前平台」即可。知乎不支持外链图片，必须用它自己的图片服务。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>各平台发布格式要求：<a href="/siyuan-plugin-publisher/guide/faq.html">常见问题</a></li><li>其他平台：<a href="/siyuan-plugin-publisher/platforms/">平台支持</a></li></ul>',28)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
